package main
import "fmt"
func calculate(a,b int, op string)(int,error){switch op{case "+":return a+b,nil;case "-":return a-b,nil;case "*":return a*b,nil;case "/":if b==0{return 0,fmt.Errorf("division by zero")};return a/b,nil;default:return 0,fmt.Errorf("unsupported operation: %s",op)}}
func main(){for _,op:=range []string{"+","-","*","/"}{v,err:=calculate(12,3,op);if err!=nil{fmt.Println(err);continue};fmt.Println(op,v)}}
